// Validate the business idea before spending a single token.
const b = $input.first().json.body ?? $input.first().json;
const errors = [];
const need = (k, min) => {
  const v = b?.[k];
  if (typeof v !== "string" || v.trim().length < min) errors.push(`${k} must be a string of >= ${min} chars`);
};
need("business_idea", 40); need("sector", 2); need("target_customer", 10);
if (!Array.isArray(b?.geography) || b.geography.length === 0) errors.push("geography must be a non-empty array");
if (errors.length) throw new Error("Invalid input: " + errors.join("; "));

const canonical = (v) => {
  if (v === null || typeof v !== "object") return JSON.stringify(v);
  if (Array.isArray(v)) return "[" + v.map(canonical).join(",") + "]";
  return "{" + Object.keys(v).sort().map(k => JSON.stringify(k) + ":" + canonical(v[k])).join(",") + "}";
};
const input = {
  business_idea: b.business_idea.trim(), sector: b.sector.trim(),
  target_customer: b.target_customer.trim(), geography: b.geography,
  budget_band: b.budget_band ?? "unknown", stage: b.stage ?? "idea",
};
const enc = new TextEncoder().encode(canonical(input));
const hash = [...new Uint8Array(await crypto.subtle.digest("SHA-256", enc))]
  .map(x => x.toString(16).padStart(2, "0")).join("");
return [{ json: { run_id: crypto.randomUUID(), input, input_digest: hash } }];

// EVIDENCE LAYER — agents may cite only these source ids.
// Mirrors config/source-whitelist.yaml. Keep the two in sync.
const SOURCES = [
  { id:"S001", type:"primary_regulator", publisher:"MeitY", title:"Digital Personal Data Protection Act, 2023 and Rules", url:"https://www.meity.gov.in/", topics:["privacy","data_protection","regulatory_compliance"] },
  { id:"S002", type:"primary_regulator", publisher:"TRAI", title:"Commercial communications / DLT guidance", url:"https://trai.gov.in/", topics:["messaging","marketing"] },
  { id:"S003", type:"primary_regulator", publisher:"RBI", title:"Payment and Settlement Systems directions", url:"https://www.rbi.org.in/", topics:["payments","kyc"] },
  { id:"S004", type:"primary_regulator", publisher:"CERT-In", title:"Cyber incident reporting directions", url:"https://www.cert-in.org.in/", topics:["security","incident_response"] },
  { id:"S005", type:"primary_regulator", publisher:"MCA", title:"Company incorporation and compliance", url:"https://www.mca.gov.in/", topics:["entity","incorporation"] },
  { id:"S006", type:"primary_regulator", publisher:"GSTN", title:"GST registration, returns and rates", url:"https://www.gst.gov.in/", topics:["tax","gst"] },
  { id:"S007", type:"primary_regulator", publisher:"Udyam / MSME", title:"Udyam registration", url:"https://udyamregistration.gov.in/", topics:["entity","msme"] },
  { id:"S008", type:"primary_regulator", publisher:"IP India", title:"Trademark search and filing", url:"https://ipindia.gov.in/", topics:["brand","trademark"] },
  { id:"S009", type:"primary_regulator", publisher:"FSSAI", title:"Food licensing, labelling and claims", url:"https://www.fssai.gov.in/", topics:["food","licensing"] },
  { id:"S010", type:"primary_regulator", publisher:"DGFT", title:"Import/export policy and licensing", url:"https://www.dgft.gov.in/", topics:["import","export"] },
  { id:"S011", type:"government_statistics", publisher:"MoSPI", title:"National accounts and consumption statistics", url:"https://www.mospi.gov.in/", topics:["market_research","demographics","gdp"] },
  { id:"S012", type:"government_statistics", publisher:"Census of India", title:"Population and urbanisation data", url:"https://censusindia.gov.in/", topics:["demographics","population"] },
  { id:"S013", type:"government_statistics", publisher:"Ministry of Finance", title:"Economic Survey and Budget documents", url:"https://www.indiabudget.gov.in/", topics:["macro","sector_policy"] },
  { id:"S014", type:"primary_regulator", publisher:"Ministry of Labour", title:"Labour codes and wage regulation", url:"https://labour.gov.in/", topics:["hr","employment"] },
];
const today = new Date().toISOString().slice(0,10);
const block = ["## AVAILABLE SOURCES", "",
  "You may cite ONLY these source ids. Anything not supported by one of them",
  "belongs in assumptions[] or estimates[], never in facts[].", ""]
  .concat(SOURCES.map(s => `- ${s.id} | ${s.type} | ${s.publisher} — ${s.title} <${s.url}>`))
  .join("\n");
const prev = $input.first().json;
return [{ json: { ...prev, sources: SOURCES.map(s => ({ ...s, accessed_at: today, retrieval_method: "none", published_at: null })), source_block: block } }];

// Bind each response to its agent BY NODE NAME, never by array position.
// Positional mapping was the bug that could file financials as competitive analysis.
const AGENTS = [
  {
    "id": "market_research",
    "name": "Agent 1 - Market Research"
  },
  {
    "id": "regulatory_compliance",
    "name": "Agent 2 - Regulatory Compliance"
  },
  {
    "id": "market_entry",
    "name": "Agent 3 - Market Entry"
  },
  {
    "id": "competitive_landscape",
    "name": "Agent 4 - Competitive Landscape"
  },
  {
    "id": "go_to_market",
    "name": "Agent 5 - Go To Market"
  },
  {
    "id": "financial_projections",
    "name": "Agent 6 - Financial Projections"
  },
  {
    "id": "risk_management",
    "name": "Agent 7 - Risk Management"
  },
  {
    "id": "implementation_roadmap",
    "name": "Agent 8 - Implementation Roadmap"
  }
];
const meta = $("Build Source Pack").first().json;
const out = [];
const failures = [];
for (const a of AGENTS) {
  let raw;
  try { raw = $(a.name).first().json; } catch (e) { failures.push(`${a.id}: no output`); continue; }
  const text = raw?.content?.[0]?.text;
  if (typeof text !== "string") { failures.push(`${a.id}: missing content[0].text`); continue; }
  if (raw?.stop_reason === "max_tokens") failures.push(`${a.id}: TRUNCATED (stop_reason=max_tokens)`);
  let doc;
  try {
    doc = JSON.parse(text.trim().replace(/^```(?:json)?/,"").replace(/```$/,"").trim());
  } catch (e) { failures.push(`${a.id}: invalid JSON — ${e.message}`); continue; }
  doc.run_id = meta.run_id;
  doc.input_digest = meta.input_digest;
  if (doc.agent) doc.agent.id = a.id;
  out.push(doc);
}
return [{ json: { run_id: meta.run_id, input: meta.input, input_digest: meta.input_digest, agents: out, failures, agent_count: out.length } }];

// Hand off to the repository pipeline, which owns schema validation,
// synthesis, rendering and the guarded GitHub publish.
//   npm run pipeline -- --input <input.json> --agents <dir>
const d = $input.first().json;
if (d.failures?.length) {
  console.log("Agent failures:\n  " + d.failures.join("\n  "));
}
return [{ json: {
  run_id: d.run_id,
  input: d.input,
  input_digest: d.input_digest,
  agents_succeeded: d.agent_count,
  agents_expected: 8,
  failures: d.failures,
  agent_outputs: d.agents,
  next_step: "Write agent_outputs to a directory, then run: npm run pipeline -- --agents <dir>",
} }];
